const ROTOR = ["platform", "center_pole", "pole1", "bear1_body", "bear1_head", "bear1_ear1", "bear1_ear2", "bear1_snout", "bear1_eye1", "bear1_eye2", "bear1_nose", "pole2", "bunny2_body", "bunny2_head", "bunny2_ear1", "bunny2_ear2", "bunny2_tail", "bunny2_eye1", "bunny2_eye2", "bunny2_nose", "pole3", "bear3_body", "bear3_head", "bear3_ear1", "bear3_ear2", "bear3_snout", "bear3_eye1", "bear3_eye2", "bear3_nose", "pole4", "bunny4_body", "bunny4_head", "bunny4_ear1", "bunny4_ear2", "bunny4_tail", "bunny4_eye1", "bunny4_eye2", "bunny4_nose", "pole5", "bear5_body", "bear5_head", "bear5_ear1", "bear5_ear2", "bear5_snout", "bear5_eye1", "bear5_eye2", "bear5_nose", "pole6", "bunny6_body", "bunny6_head", "bunny6_ear1", "bunny6_ear2", "bunny6_tail", "bunny6_eye1", "bunny6_eye2", "bunny6_nose", "roof_band", "bead1", "bead2", "bead3", "bead4", "bead5", "bead6", "bead7", "bead8", "bead9", "bead10", "bead11", "bead12", "roof_stripe1", "roof_stripe2", "roof_stripe3", "roof_stripe4", "roof_stripe5", "roof_stripe6", "roof_stripe7", "roof_stripe8", "roof_stripe9", "roof_stripe10", "roof_stripe11", "roof_stripe12", "finial"];
const ANIMALS = {"bear1": ["bear1_body", "bear1_head", "bear1_ear1", "bear1_ear2", "bear1_snout", "bear1_eye1", "bear1_eye2", "bear1_nose"], "bunny2": ["bunny2_body", "bunny2_head", "bunny2_ear1", "bunny2_ear2", "bunny2_tail", "bunny2_eye1", "bunny2_eye2", "bunny2_nose"], "bear3": ["bear3_body", "bear3_head", "bear3_ear1", "bear3_ear2", "bear3_snout", "bear3_eye1", "bear3_eye2", "bear3_nose"], "bunny4": ["bunny4_body", "bunny4_head", "bunny4_ear1", "bunny4_ear2", "bunny4_tail", "bunny4_eye1", "bunny4_eye2", "bunny4_nose"], "bear5": ["bear5_body", "bear5_head", "bear5_ear1", "bear5_ear2", "bear5_snout", "bear5_eye1", "bear5_eye2", "bear5_nose"], "bunny6": ["bunny6_body", "bunny6_head", "bunny6_ear1", "bunny6_ear2", "bunny6_tail", "bunny6_eye1", "bunny6_eye2", "bunny6_nose"]};
const T = 8.0;
const BOB = 2.0;

export const clips = {
  spin: {
    label: "Turn once (8 s)",
    duration: T,
    loop: true,
    update(t, m) {
      const angle = 360 * t / T;
      Object.values(ANIMALS).forEach((parts, i) => {
        const dz = BOB * Math.sin(2 * Math.PI * (3 * t / T) + i * Math.PI / 3);
        parts.forEach((p) => m.get(p).translate([0, 0, dz]));
      });
      ROTOR.forEach((p) => m.get(p).rotate([0, 0, 1], angle, [0, 0, 0]));
    },
  },
};
